"""Write docs/COMPONENTS.md from echos/components.py (the single registry the API and the UI also read). Do not edit the .md by hand.
Usage: python scripts/docgen/make_components_doc.py   (tests/test_team.py fails if the file is out of date)"""
from __future__ import annotations

from pathlib import Path

from echos.components import COMPONENTS

ROOT = Path(__file__).resolve().parents[2]
KIND = {"detector": "Detector: senses and turns data into evidence. Never decides a status and never sends anything.",
        "agent": "Agent: has a goal, chooses its next step, uses tools, acts and leaves a trace.",
        "infra": "Infrastructure: keeps the others running."}


def render() -> str:
    out = ["# Components: detectors, agents and infrastructure", "",
           "Generated by `scripts/docgen/make_components_doc.py` from `echos/components.py`; the API (`GET /api/components`) and the web app (How it works) read the same registry.", "",
           "ECHOS watches the sensors and vital signs of one older person and tells their caregiver and clinician, at once when a fall or critical reading is detected, "
           "and once a day whether anything differs from that person's own usual. Decision support, not a diagnosis; a language model never decides an emergency.", ""]
    for kind in ("detector", "agent", "infra"):
        out += [f"## {kind.capitalize()}s" if kind != "infra" else "## Infrastructure", "", KIND[kind], ""]
        for c in (x for x in COMPONENTS if x["kind"] == kind):
            out += [f"### {c['name']} (`{c['id']}`)", "", c["role"], "",
                    f"- **Takes in:** {c['inputs']}", f"- **Produces:** {c['outputs']}", f"- **If it fails:** {c['on_failure']}", f"- **Never:** {c['never']}", ""]
    out += ["## How they talk", "",
            "Agents hand cases over through the SQLite message bus (`agent_message`, `echos/team/bus.py`): Triage -> Case Investigator (`case_opened`), "
            "Case Investigator -> Care Coordinator and Report agent (`case_file_ready`), Care Coordinator -> everyone (`alert_escalated`). "
            "The web app shows the bus under *How it works* and the latest hand-overs on *Today*.", ""]
    return "\n".join(out)


if __name__ == "__main__":
    (ROOT / "docs" / "COMPONENTS.md").write_text(render())
    print("wrote docs/COMPONENTS.md")
